    {
      "id": 1,
      "claim": "Total loans taken during college = 4 years × $50,000 per year = $200,000",
      "evidence": "Problem states Jim receives $50,000 in loans each year for a 4‑year program.",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Lost earnings while in school = 4 years × $25,000 per year = $100,000",
      "evidence": "If Jim had not attended college he would have earned $25k per year.",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Total amount to recover = loans + lost earnings = $200,000 + $100,000 = $300,000",
      "evidence": "Add the amounts from steps 1 and 2.",
      "weight": 0.2,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Post‑college salary = 3 × $25,000 = $75,000 per year",
      "evidence": "Degree triples his pre‑college income of $25,000.",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Years needed to earn $300,000 at $75,000 per year = $300,000 ÷ $75,000 = 4 years",
      "evidence": "Divide the total deficit (step 3) by the annual earnings after college (step 4). All earnings, including the $25,000 that would have been earned anyway, count toward repaying the deficit.",
      "weight": 0.4,
      "depends_on": [3, 4]
    }
  ],
  "answer": "4",
  "confidence": 0.78,
  "considered": [
    {
      "answer": "6",
      "reason_rejected": "Uses only the incremental $50,000 increase over the baseline salary. The question asks how long to earn the total amount equivalent to the loans and lost wages, not just the extra amount beyond the baseline."
    },
    {
      "answer": "12",
      "reason_rejected": "Divides the deficit by the pre‑college salary, ignoring the higher post‑college earnings."
    }
